<!doctype html><html lang="<?php echo atlas_h(atlas_lang()); ?>"><head><title><?php echo $it?'Documentazione LJSF 3':'LJSF 3 Documentation'; ?></title><?php require __DIR__.'/css/page_header.php'; page_header('.'); ?></head><body>
